isValidVect(mat):=(is(showratvars(mat) = [x]) or is(showratvars(mat) = [])) and is(quotient(mat,x**4) = 0);
isValidInput(lst):= if length(lst) = 5 then block(temp:map(isValidVect,lst), temp[1] and temp[2] and temp[3] and temp[4] and temp[5]) else false;
fixVect(mat):=matrix([ev(mat,x=0)],[coeff(mat,x)],[coeff(mat,x**2)],[coeff(mat,x**3)]);
vectorEquiv(lst):=if isValidInput(lst) then map(fixVect,lst) else [matrix([0]),matrix([0]),matrix([0]),matrix([0]),matrix([0])];

